var t=`0119-okroshka`;var n=`world-0119`;var r=`RU`;var s=`eastern-europe`;var o=4;var a=79;var l={en:`Okroshka`,ua:`Окрошка`};var g={en:`A classic dish from Russia, featuring potato, chicken egg, kefir, cucumber. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Росія. Основні складники: картопля, куряче яйце, кефір, огірок. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`potato`,360,`g`],[`chicken-egg`,3,`pcs`],[`water`,850,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 40 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 40 хвилин.`,t:[`rapid-chilling`],m:40,i:[[`kefir`,950,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`cucumber`,270,`g`],[`radish`,180,`g`],[`green-onion`,90,`g`],[`dill`,25,`g`],[`smoked-ham`,240,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:4,i:[[`dijon-mustard`,18,`g`],[`table-salt`,null,`to_taste`]]}];var c={slug:t,id:n,country:`RU`,region:s,servings:4,minutes:79,title:l,text:g,steps:d};export{r as country,c as default,n as id,a as minutes,s as region,o as servings,t as slug,d as steps,g as text,l as title};